import numpy as np
def read(p):
    L=open(p).read().split('\n')
    n=int(L[0]); at=[]
    for l in L[2:2+n]:
        q=l.split(); at.append((q[0],np.array(list(map(float,q[1:4])))))
    return at
at=read('answer_opt2.xyz')
cd=at[0][1]
for i in (1,4,7,19,31,43):
    print(i, at[i][0], round(np.linalg.norm(at[i][1]-cd),3))
def ang(a,b,c):
    v1=at[a][1]-at[b][1]; v2=at[c][1]-at[b][1]
    return np.degrees(np.arccos(v1.dot(v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))
print('NCS', round(ang(1,2,3),1), round(ang(4,5,6),1), 'axial', round(ang(1,0,4),1))
